<div class="prod-desc-content-markers">	<?php for ($i = 1; $i <= 21; $i++): ?>		<?php if (!empty($product->{"char$i"})): ?>			<div class="prod-desc-marker">				<div class="desc-marker-title">					<p><?= $product->{"char$i"} ?>:</p>				</div>				<div class="desc-marker-val">					<p><?= $product->{"val$i"} ?></p>					<?php if (!empty($product->{"mesure$i"})): ?>						<p>&nbsp;<?= $product->{"mesure$i"} ?></p>					<?php endif; ?>				</div>			</div>		<?php endif; ?>	<?php endfor; ?></div>